insert into app.lesson_blocks (id, lesson_id, position, type, content, answer_key, settings)
      values ('00000000-0000-4000-8000-000000000024', '00000000-0000-4000-8000-000000000022', 1, 'rich_text', '{"markdown":"**Artificial Intelligence (AI)** is when computers learn *patterns* from lots of examples, so they can make predictions or create new things.\n\nYou already use AI every day:\n- 🎵 Music apps suggesting songs\n- 🗺️ Maps finding the fastest route\n- 📷 Phone cameras recognising faces"}'::jsonb, '{}'::jsonb, '{"points":1,"required":true}'::jsonb) on conflict (id) do nothing;
