      values ('00000000-0000-4000-8000-000000000028', '00000000-0000-4000-8000-000000000022', 5, 'key_terms', '{"title":"Key terms","terms":[{"term":"Artificial Intelligence","definition":"Computer systems that learn from data to make predictions or create content.","link":""},{"term":"Data","definition":"Examples (text, pictures, numbers) that an AI learns from.","link":""},{"term":"Prompt","definition":"The instruction you give to an AI tool.","link":""}]}'::jsonb, '{}'::jsonb, '{"points":1,"required":true}'::jsonb) on conflict (id) do nothing;
