      values ('00000000-0000-4000-8000-00000000002b', '00000000-0000-4000-8000-000000000022', 8, 'mcq', '{"question":"Select ALL the things AI can do.","multiple":true,"options":[{"id":"a","text":"Recognise faces in photos"},{"id":"b","text":"Suggest the fastest route"},{"id":"c","text":"Feel emotions like humans"},{"id":"d","text":"Translate languages"}]}'::jsonb, '{"correct":["a","b","d"],"explanation":"AI can recognise, predict and translate — but it does not have feelings.","optionFeedback":{}}'::jsonb, '{"points":1,"required":true}'::jsonb) on conflict (id) do nothing;
