insert into app.lesson_versions (id, lesson_id, program_id, version_no, snapshot, note, published_by)
    values ('00000000-0000-4000-8000-000000000031', '00000000-0000-4000-8000-000000000022', '00000000-0000-4000-8000-00000000000f', 1, '{"title":"What is AI?","summary":"Meet AI, see where you already use it, and test yourself.","free_navigation":false,"is_assessment":false,"estimated_minutes":15,"blocks":[{"id":"00000000-0000-4000-8000-000000000023","type":"heading","content":{"text":"Welcome, Spark Rookie! ⚡","level":2},"answer_key":{},"settings":{"points":1,"required":true}},{"id":"00000000-0000-4000-8000-000000000024","type":"rich_text","content":{"markdown":"**Artificial Intelligence (AI)** is when computers learn *patterns* from lots of examples, so they can make predictions or create new things.\n\nYou already use AI every day:\n- 🎵 Music apps suggesting songs\n- 🗺️ Maps finding the fastest route\n- 📷 Phone cameras recognising faces"},"answer_key":{},"settings":{"points":1,"required":true}},{"id":"00000000-0000-4000-8000-000000000025","type":"callout","content":{"variant":"tip","title":"Think of it like this","markdown":"AI is like a student who has read millions of books — very fast, but it can still make mistakes!"},"answer_key":{},"settings":{"points":1,"required":true}},{"id":"00000000-0000-4000-8000-000000000026","type":"image","content":{"src":"/seed/robot.svg","alt":"A friendly blue cartoon robot with an orange antenna","caption":"AI is a tool — you are the explorer in charge."},"answer_key":{},"settings":{"points":1,"required":true}},{"id":"00000000-0000-4000-8000-000000000027","type":"video","content":{"url":"https://www.youtube.com/watch?v=a0_lo_GDcFw","title":"What is Artificial Intelligence? (sample video — replace with your own)"},"answer_key":{},"settings":{"points":1,"required":true}},{"id":"00000000-0000-4000-8000-000000000028","type":"key_terms","content":{"title":"Key terms","terms":[{"term":"Artificial Intelligence","definition":"Computer systems that learn from data to make predictions or create content.","link":""},{"term":"Data","definition":"Examples (text, pictures, numbers) that an AI learns from.","link":""},{"term":"Prompt","definition":"The instruction you give to an AI tool.","link":""}]},"answer_key":{},"settings":{"points":1,"required":true}},{"id":"00000000-0000-4000-8000-000000000029","type":"flashcards","content":{"cards":[{"front":"What does AI stand for?","back":"Artificial Intelligence"},{"front":"What does an AI learn from?","back":"Data — lots of examples"},{"front":"Is AI always right?","back":"No! Always check important facts."}]},"answer_key":{},"settings":{"points":1,"required":true}},{"id":"00000000-0000-4000-8000-00000000002a","type":"mcq","content":{"question":"Which of these uses AI?","multiple":false,"options":[{"id":"a","text":"A light switch"},{"id":"b","text":"A music app suggesting songs"},{"id":"c","text":"A pencil"}]},"answer_key":{"correct":["b"],"explanation":"Music apps learn from what you listen to and predict what you''ll like next.","optionFeedback":{"a":"A switch just turns on or off — no learning involved."}},"settings":{"points":1,"required":true}},{"id":"00000000-0000-4000-8000-00000000002b","type":"mcq","content":{"question":"Select ALL the things AI can do.","multiple":true,"options":[{"id":"a","text":"Recognise faces in photos"},{"id":"b","text":"Suggest the fastest route"},{"id":"c","text":"Feel emotions like humans"},{"id":"d","text":"Translate languages"}]},"answer_key":{"correct":["a","b","d"],"explanation":"AI can recognise, predict and translate — but it does not have feelings.","optionFeedback":{}},"settings":{"points":1,"required":true}},{"id":"00000000-0000-4000-8000-00000000002c","type":"fill_blank","content":{"text":"AI stands for Artificial [[1]]. It learns patterns from [[2]]."},"answer_key":{"blanks":{"1":["intelligence"],"2":["data","examples"]},"caseSensitive":false,"explanation":"AI = Artificial Intelligence, and it learns from data."},"settings":{"points":1,"required":true}},{"id":"00000000-0000-4000-8000-00000000002d","type":"sort","content":{"prompt":"Put the steps of how an AI learns in order.","items":[{"id":"s4","text":"Check and improve"},{"id":"s1","text":"Collect lots of examples (data)"},{"id":"s2","text":"Find patterns in the data"},{"id":"s3","text":"Make a prediction"}]},"answer_key":{"order":["s1","s2","s3","s4"],"explanation":"Data → patterns → prediction → improvement."},"settings":{"points":1,"required":true}},{"id":"00000000-0000-4000-8000-00000000002e","type":"match","content":{"prompt":"Match each AI tool to what it does.","left":[{"id":"l1","text":"Maps app"},{"id":"l2","text":"Translator"},{"id":"l3","text":"Photo app"}],"right":[{"id":"r3","text":"Groups photos by face"},{"id":"r2","text":"Changes Kannada to English"},{"id":"r1","text":"Finds the fastest route"}]},"answer_key":{"pairs":{"l1":"r1","l2":"r2","l3":"r3"},"explanation":"Each tool uses AI for a different job."},"settings":{"points":1,"required":true}},{"id":"00000000-0000-4000-8000-00000000002f","type":"walkthrough","content":{"steps":[{"title":"Spot it","markdown":"Look around your home for one device that uses AI.","image":""},{"title":"Name it","markdown":"Write down what it predicts or creates.","image":""},{"title":"Share it","markdown":"Tell your trainer in the next lab session!","image":""}]},"answer_key":{},"settings":{"points":1,"required":true}},{"id":"00000000-0000-4000-8000-000000000030","type":"file","content":{"url":"/seed/spark-rookie-cheatsheet.txt","fileName":"Spark Rookie cheat sheet","description":"A one-page summary to keep."},"answer_key":{},"settings":{"points":1,"required":true}}]}'::jsonb, 'Initial seed', '00000000-0000-4000-8000-000000000002') on conflict (id) do nothing;
update app.lessons set status = 'published', published_version_id = '00000000-0000-4000-8000-000000000031', has_unpublished_changes = false where id = '00000000-0000-4000-8000-000000000022';
insert into app.lessons (id, module_id, position, title, summary, is_assessment, status, estimated_minutes)
    values ('00000000-0000-4000-8000-000000000032', '00000000-0000-4000-8000-000000000021', 1, 'Your first prompt', 'Learn the Role-Task-Context-Format recipe and build your first prompt. (Level assessment)', true, 'draft', 15) on conflict (id) do nothing;
insert into app.lesson_blocks (id, lesson_id, position, type, content, answer_key, settings)
      values ('00000000-0000-4000-8000-000000000033', '00000000-0000-4000-8000-000000000032', 0, 'callout', '{"variant":"remember","title":"Golden rule","markdown":"Never type personal information (phone number, address, passwords) into any AI tool."}'::jsonb, '{}'::jsonb, '{"points":1,"required":true}'::jsonb) on conflict (id) do nothing;
insert into app.lesson_blocks (id, lesson_id, position, type, content, answer_key, settings)
      values ('00000000-0000-4000-8000-000000000034', '00000000-0000-4000-8000-000000000032', 1, 'rich_text', '{"markdown":"A great prompt has **four parts**:\n\n1. **Role** — who should the AI act as?\n2. **Task** — what exactly should it do?\n3. **Context** — what background does it need?\n4. **Format** — how should the answer look?"}'::jsonb, '{}'::jsonb, '{"points":1,"required":true}'::jsonb) on conflict (id) do nothing;
insert into app.lesson_blocks (id, lesson_id, position, type, content, answer_key, settings)
      values ('00000000-0000-4000-8000-000000000035', '00000000-0000-4000-8000-000000000032', 2, 'short_answer', '{"question":"In one word: what do we call the instruction we give to an AI?","placeholder":"Type one word","minWords":1}'::jsonb, '{"acceptable":["prompt","a prompt"],"explanation":"It''s called a prompt."}'::jsonb, '{"points":1,"required":true}'::jsonb) on conflict (id) do nothing;
insert into app.lesson_blocks (id, lesson_id, position, type, content, answer_key, settings)
      values ('00000000-0000-4000-8000-000000000036', '00000000-0000-4000-8000-000000000032', 3, 'prompt_builder', '{"instructions":"Build a prompt that asks an AI to help you prepare for a science quiz.","scenario":"You have a Class 9 science quiz on ''Light and reflection'' next week.","hints":{"role":"e.g. You are a friendly science teacher…","task":"e.g. Create 5 practice questions…","context":"e.g. I am in Class 9, studying reflection…","format":"e.g. A numbered list with answers at the end"},"minWordsPerField":3,"checklist":[{"id":"c1","text":"My prompt has no personal information"},{"id":"c2","text":"My task is specific (says exactly what I want)"}]}'::jsonb, '{}'::jsonb, '{"points":1,"required":true}'::jsonb) on conflict (id) do nothing;
insert into app.lesson_blocks (id, lesson_id, position, type, content, answer_key, settings)
      values ('00000000-0000-4000-8000-000000000037', '00000000-0000-4000-8000-000000000032', 4, 'try_it', '{"title":"Teach an AI to recognise doodles","steps":["Click the button to open Quick, Draw! in a new tab.","Draw the 6 objects it asks for.","Notice how the AI guesses while you draw!","Come back here and mark it as done."],"toolName":"Quick, Draw!","toolUrl":"https://quickdraw.withgoogle.com/","proof":"optional"}'::jsonb, '{}'::jsonb, '{"points":1,"required":true}'::jsonb) on conflict (id) do nothing;
insert into app.lesson_blocks (id, lesson_id, position, type, content, answer_key, settings)
      values ('00000000-0000-4000-8000-000000000038', '00000000-0000-4000-8000-000000000032', 5, 'checklist', '{"title":"Before you finish","items":[{"id":"k1","text":"I know what AI is"},{"id":"k2","text":"I know the 4 parts of a good prompt"},{"id":"k3","text":"I will never share personal info with AI"}]}'::jsonb, '{}'::jsonb, '{"points":1,"required":true}'::jsonb) on conflict (id) do nothing;
insert into app.lesson_blocks (id, lesson_id, position, type, content, answer_key, settings)
      values ('00000000-0000-4000-8000-000000000039', '00000000-0000-4000-8000-000000000032', 6, 'mcq', '{"question":"Which part of a prompt says HOW the answer should look?","multiple":false,"options":[{"id":"a","text":"Role"},{"id":"b","text":"Task"},{"id":"c","text":"Context"},{"id":"d","text":"Format"}]}'::jsonb, '{"correct":["d"],"explanation":"Format describes the shape of the answer — list, table, poem…","optionFeedback":{}}'::jsonb, '{"points":2,"required":true}'::jsonb) on conflict (id) do nothing;
insert into app.lesson_blocks (id, lesson_id, position, type, content, answer_key, settings)
      values ('00000000-0000-4000-8000-00000000003a', '00000000-0000-4000-8000-000000000032', 7, 'submission', '{"kind":"reflection","prompt":"In 3–4 sentences: where could AI help you in your studies, and what should you be careful about?","accepts":["text"],"rubric":[{"criterion":"Ideas","description":"Gives a realistic use of AI","maxPoints":5},{"criterion":"Responsibility","description":"Mentions checking facts or privacy","maxPoints":5}]}'::jsonb, '{}'::jsonb, '{"points":1,"required":true}'::jsonb) on conflict (id) do nothing;
