    values ('00000000-0000-4000-8000-00000000003b', '00000000-0000-4000-8000-000000000032', '00000000-0000-4000-8000-00000000000f', 1, '{"title":"Your first prompt","summary":"Learn the Role-Task-Context-Format recipe and build your first prompt. (Level assessment)","free_navigation":false,"is_assessment":true,"estimated_minutes":15,"blocks":[{"id":"00000000-0000-4000-8000-000000000033","type":"callout","content":{"variant":"remember","title":"Golden rule","markdown":"Never type personal information (phone number, address, passwords) into any AI tool."},"answer_key":{},"settings":{"points":1,"required":true}},{"id":"00000000-0000-4000-8000-000000000034","type":"rich_text","content":{"markdown":"A great prompt has **four parts**:\n\n1. **Role** — who should the AI act as?\n2. **Task** — what exactly should it do?\n3. **Context** — what background does it need?\n4. **Format** — how should the answer look?"},"answer_key":{},"settings":{"points":1,"required":true}},{"id":"00000000-0000-4000-8000-000000000035","type":"short_answer","content":{"question":"In one word: what do we call the instruction we give to an AI?","placeholder":"Type one word","minWords":1},"answer_key":{"acceptable":["prompt","a prompt"],"explanation":"It''s called a prompt."},"settings":{"points":1,"required":true}},{"id":"00000000-0000-4000-8000-000000000036","type":"prompt_builder","content":{"instructions":"Build a prompt that asks an AI to help you prepare for a science quiz.","scenario":"You have a Class 9 science quiz on ''Light and reflection'' next week.","hints":{"role":"e.g. You are a friendly science teacher…","task":"e.g. Create 5 practice questions…","context":"e.g. I am in Class 9, studying reflection…","format":"e.g. A numbered list with answers at the end"},"minWordsPerField":3,"checklist":[{"id":"c1","text":"My prompt has no personal information"},{"id":"c2","text":"My task is specific (says exactly what I want)"}]},"answer_key":{},"settings":{"points":1,"required":true}},{"id":"000