    values ('00000000-0000-4000-8000-000000000044', '00000000-0000-4000-8000-00000000003e', '00000000-0000-4000-8000-000000000010', 1, '{"title":"Hello, Python","summary":"Your first Python program.","free_navigation":false,"is_assessment":false,"estimated_minutes":15,"blocks":[{"id":"00000000-0000-4000-8000-00000000003f","type":"rich_text","content":{"markdown":"Python is one of the most popular programming languages in the world.\n\n```python\nprint(\"Hello, Gadag!\")\n```\n\n`print()` shows text on the screen."},"answer_key":{},"settings":{"points":1,"required":true}},{"id":"00000000-0000-4000-8000-000000000040","type":"callout","content":{"variant":"tip","title":"Coming in Phase 4","markdown":"This lesson will include an in-browser code exercise (Pyodide) with auto-graded tests."},"answer_key":{},"settings":{"points":1,"required":true}},{"id":"00000000-0000-4000-8000-000000000041","type":"key_terms","content":{"title":"Key terms","terms":[{"term":"Function","definition":"A named block of code that does a job, like print().","link":""},{"term":"String","definition":"Text inside quotes, like \"Hello\".","link":""}]},"answer_key":{},"settings":{"points":1,"required":true}},{"id":"00000000-0000-4000-8000-000000000042","type":"mcq","content":{"question":"What does print(\"Hi\") do?","multiple":false,"options":[{"id":"a","text":"Shows Hi on the screen"},{"id":"b","text":"Prints on paper"},{"id":"c","text":"Deletes Hi"}]},"answer_key":{"correct":["a"],"explanation":"print() displays output on the screen.","optionFeedback":{}},"settings":{"points":1,"required":true}},{"id":"00000000-0000-4000-8000-000000000043","type":"fill_blank","content":{"text":"To show text in Python we use the [[1]] function."},"answer_key":{"blanks":{"1":["print","print()"]},"caseSensitive":false,"explanation":""},"settings":{"points":1,"required":true}}]}'::jsonb, 'Initial seed', '00000000-0000-4000-8000-000000000002') on conflict (id) do nothing;
